const $=s=>document.querySelector(s), main=$('#main'), dialog=$('#editor');
let db, exhibitions=[], draft, urls=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=o=>{let u=URL.createObjectURL(o.blob);urls.push(u);return u};
const cleanup=()=>{urls.forEach(URL.revokeObjectURL);urls=[]};
const sample={id:'sample',title:'My first apartment',intro:'A small beginning. A place that slowly became mine.',objects:[{title:'The first set of keys',note:'I picked these up two days before starting my new job.',emoji:'🗝️'},{title:'My one good mug',note:'The only mug I owned for the first month.',emoji:'☕'},{title:'Sunday mornings',note:'The market outside my window. A sound I came to love.',emoji:'🌿'}]};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('museum-of-you',1);r.onupgradeneeded=()=>r.result.createObjectStore('exhibitions',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});exhibitions=await new Promise((resolve,reject)=>{const r=db.transaction('exhibitions').objectStore('exhibitions').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});home()}catch(e){main.innerHTML='<h1>Your museum needs browser storage.</h1><p>Please enable site storage and reload to save your exhibitions.</p>';document.querySelectorAll('[data-new]').forEach(b=>b.disabled=true)}}
function home(){cleanup();main.innerHTML=`<section class="hero"><div><span class="eyebrow">A LIFE, COLLECTED.</span><h1>Some things deserve<br>a little <em>exhibition.</em></h1><p>The ordinary, the unforgettable, the beautifully in-between. Make a little room for your memories.</p><button data-new>Create an exhibition <span>↗</span></button></div><div class="still-life" aria-hidden="true"><span class="pencil-note">a few things worth keeping ↴</span><div class="paper-card"><div class="illustration">🗝️</div><small>where it all began</small></div><div class="ticket"><small>ADMIT ONE · YOUR LIFE</small><b>The little things.</b><small>KEEP FOREVER &nbsp; Nº 003</small></div><span class="spark">✳</span></div></section><div class="collection-head"><h2>Your exhibitions</h2><span>${exhibitions.length} personal ${exhibitions.length===1?'exhibition':'exhibitions'}</span></div><section class="grid">${exhibitions.map(e=>card(e)).join('')}<button class="exhibition" data-view="sample"><div class="cover sample-cover"><span class="badge">SAMPLE EXHIBITION</span><span class="sample-art">🗝️</span></div><h3>My first apartment</h3><p>3 objects · A little inspiration</p></button><button class="add-card" data-new><strong>＋</strong><span>A new chapter starts here</span></button></section><p class="bottom-note"><em>A museum doesn't have to be grand. It just has to be yours.</em>Your exhibitions are stored on this browser. Clearing site data removes them.<br>Uploads stay on this device. There is no cloud backup or sharing yet.</p>`;bind()}
function card(e){const o=e.objects[0];return `<button class="exhibition" data-view="${esc(e.id)}"><div class="cover"><span class="badge">${e.objects.length<3?'DRAFT':'ONLY ON THIS BROWSER'}</span>${o?o.type==='image'?`<img src="${url(o)}" alt="">`:'<span class="cover-audio">♫</span>':'<span class="cover-audio">＋</span>'}</div><h3>${esc(e.title)}</h3><p>${e.objects.length} objects · ${new Date(e.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</p></button>`}
function bind(){main.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>edit());main.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view))}
function view(id){cleanup();const e=id==='sample'?sample:exhibitions.find(x=>x.id===id);if(!e)return home();main.innerHTML=`<button class="back" id="back">← Your museum</button><div class="view-title"><span class="eyebrow">${id==='sample'?'A FICTIONAL SAMPLE EXHIBITION':'YOUR PERSONAL COLLECTION'}</span><h1>${esc(e.title)}</h1><p>${esc(e.intro)}</p><div class="view-actions">${id==='sample'?'<button data-new>Make your own ↗</button>':'<button id="edit">Edit exhibition</button><button class="secondary" id="delete">Delete</button>'}</div></div><section class="gallery">${e.objects.map((o,i)=>`<figure>${o.emoji?`<div class="cover sample-cover"><span class="sample-art">${o.emoji}</span></div>`:o.type==='image'?`<img src="${url(o)}" alt="${esc(o.title||'Exhibition object '+(i+1))}">`:`<audio controls preload="metadata" src="${url(o)}"></audio>`}<figcaption><p><small>OBJECT ${String(i+1).padStart(2,'0')}</small></p><h3>${esc(o.title||'Untitled object')}</h3>${o.note?`<p>${esc(o.note)}</p>`:''}</figcaption></figure>`).join('')}</section>${e.objects.length?'':'<p class="empty-view">This chapter is waiting for its first object. Choose Edit exhibition to add one.</p>'}`;$('#back').onclick=home;bind();if(id!=='sample'){$('#edit').onclick=()=>edit(e);$('#delete').onclick=async()=>{if(!confirm(`Delete “${e.title}” and its objects? This cannot be undone.`))return;try{await write('delete',id);exhibitions=exhibitions.filter(x=>x.id!==id);home();toast('Exhibition deleted')}catch{toast('Could not delete. Please try again.')}}}window.scrollTo(0,0)}
function edit(e){draft=e?structuredClone(e):{id:crypto.randomUUID(),title:'',intro:'',objects:[]};$('#title').value=draft.title;$('#intro').value=draft.intro;$('#error').textContent='';renderObjects();dialog.showModal();$('#title').focus()}
function renderObjects(){const list=$('#objects');list.replaceChildren();$('#count').textContent=`${draft.objects.length} / 3 to get started`;draft.objects.forEach((o,i)=>{const el=document.createElement('div');el.className='object-edit';el.innerHTML=`${o.type==='image'?`<img src="${url(o)}" alt="Object preview">`:'<span class="cover-audio">♫</span>'}<div><input aria-label="Object ${i+1} title" maxlength="100" placeholder="Object title (optional)" value="${esc(o.title)}"><textarea aria-label="Object ${i+1} note" maxlength="2000" rows="2" placeholder="What would you like to remember about this?">${esc(o.note)}</textarea><div class="object-actions"><button type="button" data-up ${i===0?'disabled':''}>↑ Move earlier</button><button type="button" data-down ${i===draft.objects.length-1?'disabled':''}>↓ Move later</button><button type="button" data-remove>Remove</button></div></div>${o.type==='audio'?`<audio controls src="${url(o)}"></audio>`:''}`;el.querySelector('input').oninput=ev=>o.title=ev.target.value;el.querySelector('textarea').oninput=ev=>o.note=ev.target.value;el.querySelector('[data-remove]').onclick=()=>{draft.objects.splice(i,1);renderObjects()};el.querySelector('[data-up]').onclick=()=>{[draft.objects[i-1],draft.objects[i]]=[draft.objects[i],draft.objects[i-1]];renderObjects()};el.querySelector('[data-down]').onclick=()=>{[draft.objects[i+1],draft.objects[i]]=[draft.objects[i],draft.objects[i+1]];renderObjects()};list.append(el)})}
$('#upload').onchange=ev=>{const errors=[];for(const f of ev.target.files){if(!/^(image|audio)\//.test(f.type)){errors.push(`${f.name}: choose an image or audio file.`);continue}if(f.size>20*1024*1024){errors.push(`${f.name}: exceeds 20 MB.`);continue}draft.objects.push({id:crypto.randomUUID(),type:f.type.startsWith('image/')?'image':'audio',blob:f,title:'',note:''})}$('#error').textContent=errors.join(' ');ev.target.value='';renderObjects()};
function write(method,value){return new Promise((resolve,reject)=>{const tx=db.transaction('exhibitions','readwrite');tx.objectStore('exhibitions')[method](value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
$('#form').onsubmit=async ev=>{ev.preventDefault();const b=ev.submitter;b.disabled=true;draft.title=$('#title').value.trim()||'Untitled exhibition';draft.intro=$('#intro').value.trim();draft.updated=Date.now();try{await write('put',draft);const idx=exhibitions.findIndex(e=>e.id===draft.id);if(idx>=0)exhibitions[idx]=draft;else exhibitions.unshift(draft);dialog.close();view(draft.id);toast('Exhibition saved on this browser')}catch{$('#error').textContent='Could not save. Browser storage may be full. Your edits are still here; try removing a large file.'}finally{b.disabled=false}};
function closeEditor(){if(confirm('Close without saving these edits?')){dialog.close();home()}}
$('#close').onclick=closeEditor;dialog.addEventListener('cancel',e=>{e.preventDefault();closeEditor()});document.querySelector('header [data-new]').onclick=()=>edit();document.querySelectorAll('header a').forEach(a=>a.onclick=e=>{e.preventDefault();home()});init();
